#include "StudyCommon.hh"
#include <iomanip>
#include <iostream>
#include <array>
struct Acc {long long n=0,nhg=0;double truth=0,predDigi=0,predCal=0,lg=0,hg=0,predDigiHG=0,predCalHG=0;};
int main(int argc,char**argv)try{
 auto o=options(argc,argv,{{"input",""},{"audit",""},{"hl",""},{"mip",""},{"pedestal",""},{"out",""},{"events","10000"}});auto par=parameters(o["hl"],o["mip"],o["pedestal"]);std::map<int,double>digi;std::ifstream audit(o["audit"]);std::string line;std::getline(audit,line);while(std::getline(audit,line)){std::istringstream row(line);int id,g,nd;double mp,chi,cal,d;row>>id>>g>>mp>>chi>>nd>>cal>>d;digi[id]=d;}
 std::ifstream manifest{fs::path(o.at("input"))/"inputs/mc.tsv"};std::getline(manifest,line);auto rawPath=line.substr(0,line.find('\t'));auto truthPath=rawPath;std::string part="/decode/e-/sps/threshold/";auto at=truthPath.find(part);require(at!=std::string::npos,"Unexpected MC path");truthPath.replace(at,part.size(),"/generate/e-/sps/");auto raw=openFile(rawPath),truth=openFile(truthPath);auto*r=object<TTree>(*raw,"Raw_Hit"),*t=object<TTree>(*truth,"MC_Truth");require(r->GetEntries()==t->GetEntries(),"Truth/raw entry count mismatch");r->SetBranchStatus("*",0);t->SetBranchStatus("*",0);std::vector<int>*ri=nullptr,*ti=nullptr,*tags=nullptr;std::vector<double>*hg=nullptr,*lg=nullptr,*te=nullptr;bind(r,"CellID",&ri);bind(r,"HitTag",&tags);bind(r,"HG_Charge",&hg);bind(r,"LG_Charge",&lg);bind(t,"CellID",&ti);bind(t,"Hit_Energy",&te);std::map<std::pair<int,int>,Acc>stats;std::map<int,Acc> channels;
 auto add=[](Acc&a,double energy,double high,double low,double d,double c,bool useHG){++a.n;a.truth+=energy;a.predDigi+=energy/.305*d;a.predCal+=energy/.305*c;a.lg+=low;if(useHG){++a.nhg;a.hg+=high;a.predDigiHG+=energy/.305*d;a.predCalHG+=energy/.305*c;}};
 Long64_t count=std::min<Long64_t>(r->GetEntries(),std::stoll(o["events"]));
 for(Long64_t i=0;i<count;++i){r->GetEntry(i);t->GetEntry(i);std::map<int,double> energy;for(size_t j=0;j<ti->size();++j)require(energy.emplace(ti->at(j),te->at(j)).second,"Duplicate truth channel");for(size_t j=0;j<ri->size();++j){int id=physical(ri->at(j));if(tags->at(j)!=1||!connected(id))continue;require(energy.count(ri->at(j)),"Raw channel missing in truth");double e=energy.at(ri->at(j));if(e<.5||e>=100)continue;auto&p=par.at(id);if(p.mip<=0)continue;double qh=hg->at(j)-p.ph,ql=(lg->at(j)-p.pl)*p.gain;int category=group(id)*2+(std::abs(digi[id]-p.mip)>1e-8);int band=0;for(double edge:{1.,2.,5.,10.,30.})band+=e>=edge;bool goodHG=hg->at(j)<2400;add(stats[{category,band}],e,qh,ql,digi[id],p.mip,goodHG);if(e<2)add(channels[id],e,qh,ql,digi[id],p.mip,goodHG);}}
 fs::create_directories(o["out"]);std::ofstream out{fs::path(o.at("out"))/"truth_response.tsv"},ch{fs::path(o.at("out"))/"truth_channels.tsv"};out<<std::setprecision(12)<<"category\ttruth_band\thits\thg_hits\tLG_over_digi_prediction\tLG_over_calib_prediction\tHG_over_digi_prediction\tHG_over_calib_prediction\n";for(auto&[key,a]:stats)out<<key.first<<'\t'<<key.second<<'\t'<<a.n<<'\t'<<a.nhg<<'\t'<<a.lg/a.predDigi<<'\t'<<a.lg/a.predCal<<'\t'<<(a.predDigiHG?a.hg/a.predDigiHG:0)<<'\t'<<(a.predCalHG?a.hg/a.predCalHG:0)<<'\n';ch<<std::setprecision(12)<<"cell\tcalib_mip\tdigi_mip\thits\tHG_over_digi_prediction\tHG_over_calib_prediction\n";for(auto&[id,a]:channels)if(a.nhg>=20)ch<<id<<'\t'<<par.at(id).mip<<'\t'<<digi[id]<<'\t'<<a.nhg<<'\t'<<a.hg/a.predDigiHG<<'\t'<<a.hg/a.predCalHG<<'\n';std::cout<<"Checked "<<count<<" truth/raw events in "<<rawPath<<std::endl;r->ResetBranchAddresses();t->ResetBranchAddresses();delete ri;delete ti;delete tags;delete hg;delete lg;delete te;return 0;
}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}
